-- =====================================================================
--  SQL-MYSTERIET PÅ YRGO
--  Ett detektivspel i SQL, inspirerat av "The SQL Murder Mystery"
--  (https://github.com/NUKnightLab/sql-mysteries).
--  För MySQL 8.4.
-- =====================================================================
--
--  UPPDRAGET
--  ---------
--  Ett brott har begåtts i Göteborg och polisen behöver din hjälp.
--  Kommissarien gav dig brottsplatsrapporten, men du har lyckats tappa
--  bort den. Du minns bara vagt att brottet var en stöld ("stöld") som
--  skedde den 14 november 2025, och att den ägde rum i Göteborg.
--
--  Allt du behöver finns i den här databasen. Börja med att hämta
--  rätt brottsplatsrapport från tabellen crime_scene_report och följ
--  sedan ledtrådarna.
--
--  TIPS
--  ----
--    SHOW TABLES;                 -- vilka tabeller finns?
--    DESCRIBE crime_scene_report; -- vilka kolumner har en tabell?
--
--  KONTROLLERA DITT SVAR
--  ---------------------
--  När du tror att du har hittat tjuven, kör:
--
--    INSERT INTO solution VALUES (1, 'Förnamn Efternamn');
--    SELECT value FROM solution;
--
--  INSTALLATION
--  ------------
--    mysql -u root -p < yrgo_mystery.sql
--  eller öppna filen i MySQL Workbench och kör hela skriptet.
--
--  Alla personer och händelser är påhittade.
-- =====================================================================

SET NAMES utf8mb4;

DROP DATABASE IF EXISTS yrgo_mystery;
CREATE DATABASE yrgo_mystery CHARACTER SET utf8mb4 COLLATE utf8mb4_sv_0900_ai_ci;
USE yrgo_mystery;

CREATE TABLE drivers_license (
    id           INT PRIMARY KEY,
    age          INT NOT NULL,
    height       INT NOT NULL,
    eye_color    VARCHAR(20) NOT NULL,
    hair_color   VARCHAR(20) NOT NULL,
    gender       VARCHAR(20) NOT NULL
);

CREATE TABLE car (
    plate_number VARCHAR(10) PRIMARY KEY,
    owner_id     INT NOT NULL,
    make         VARCHAR(30) NOT NULL,
    model        VARCHAR(30) NOT NULL,
    FOREIGN KEY (owner_id) REFERENCES drivers_license (id)
);

CREATE TABLE person (
    id                  INT PRIMARY KEY,
    name                VARCHAR(100) NOT NULL,
    license_id          INT NULL,
    address_number      INT NOT NULL,
    address_street_name VARCHAR(100) NOT NULL,
    personal_number     CHAR(13) NOT NULL UNIQUE,
    FOREIGN KEY (license_id) REFERENCES drivers_license (id)
);

CREATE TABLE crime_scene_report (
    date        DATE NOT NULL,
    type        VARCHAR(30) NOT NULL,
    description TEXT NOT NULL,
    city        VARCHAR(50) NOT NULL
);

CREATE TABLE interview (
    person_id  INT NOT NULL,
    transcript TEXT NOT NULL,
    FOREIGN KEY (person_id) REFERENCES person (id)
);

CREATE TABLE yrgo_card (
    id          CHAR(5) PRIMARY KEY,
    person_id   INT NOT NULL,
    name        VARCHAR(100) NOT NULL,
    issued_date DATE NOT NULL,
    card_type   VARCHAR(20) NOT NULL,
    program     VARCHAR(50) NULL,
    FOREIGN KEY (person_id) REFERENCES person (id)
);

CREATE TABLE yrgo_access_log (
    card_id     CHAR(5) NOT NULL,
    access_date DATE NOT NULL,
    time_in     TIME NOT NULL,
    time_out    TIME NOT NULL,
    door        VARCHAR(30) NOT NULL,
    FOREIGN KEY (card_id) REFERENCES yrgo_card (id)
);

CREATE TABLE event_checkin (
    person_id  INT NOT NULL,
    event_id   INT NOT NULL,
    event_name VARCHAR(100) NOT NULL,
    date       DATE NOT NULL,
    FOREIGN KEY (person_id) REFERENCES person (id)
);

CREATE TABLE income (
    personal_number CHAR(13) PRIMARY KEY,
    annual_income   INT NOT NULL
);

CREATE TABLE drone_operator (
    operator_id     VARCHAR(20) PRIMARY KEY,
    person_id       INT NOT NULL,
    registered_date DATE NOT NULL,
    FOREIGN KEY (person_id) REFERENCES person (id)
);

CREATE TABLE remote_id_signal (
    received_at DATETIME NOT NULL,
    operator_id VARCHAR(20) NOT NULL,
    drone_lat   DECIMAL(8, 5) NOT NULL,
    drone_lon   DECIMAL(8, 5) NOT NULL,
    altitude_m  INT NOT NULL,
    pilot_lat   DECIMAL(8, 5) NOT NULL,
    pilot_lon   DECIMAL(8, 5) NOT NULL
);

CREATE TABLE toll_passage (
    plate_number VARCHAR(10) NOT NULL,
    station      VARCHAR(30) NOT NULL,
    direction    VARCHAR(3) NOT NULL,
    passed_at    DATETIME NOT NULL
);

CREATE TABLE company (
    org_number          CHAR(11) PRIMARY KEY,
    name                VARCHAR(100) NOT NULL,
    registered_date     DATE NOT NULL,
    address_street_name VARCHAR(100) NOT NULL,
    address_number      INT NOT NULL
);

CREATE TABLE company_role (
    org_number      CHAR(11) NOT NULL,
    personal_number CHAR(13) NOT NULL,
    role            VARCHAR(30) NOT NULL,
    FOREIGN KEY (org_number) REFERENCES company (org_number)
);

CREATE TABLE lia_offer (
    card_id      CHAR(5) NOT NULL,
    org_number   CHAR(11) NOT NULL,
    offered_date DATE NOT NULL,
    fee_paid     INT NOT NULL,
    FOREIGN KEY (card_id) REFERENCES yrgo_card (id),
    FOREIGN KEY (org_number) REFERENCES company (org_number)
);

CREATE TABLE solution (
    user  INT,
    value TEXT
);








CREATE TRIGGER check_solution BEFORE INSERT ON solution FOR EACH ROW
SET NEW.value = CASE SHA2(LOWER(TRIM(NEW.value)), 256)
    WHEN '7803ee1874ac3e9b646701128045b1701e1f867bbd80ed67ce2fcb7630747fb0' THEN 'Grattis, du hittade tjuven! Men vänta, det finns mer... Om du vill ha en riktig utmaning kan du försöka ta reda på vem som egentligen låg bakom stölden. Läs förhöret med tjuven. Vill du göra det ännu svårare? Försök klara det med högst två SQL-frågor. Använd samma INSERT-sats för att kontrollera ditt svar.'
    WHEN '11054c264aef8f525d4279fd09d0e49aee43426b7cfabf47ad28510010b140cd' THEN 'Grattis, du hittade hjärnan bakom stölden! Projekt Kråka är tillbaka på Yrgo i tid till examensmässan. Men vänta... Cecilia Wallins namn förekommer i en annan polisutredning, där hennes vittnesmål skickade polisen åt fel håll. Nu när vi vet att hon inte går att lita på kanske det fallet går att lösa. Sök efter henne i brottsplatsrapporterna!'
    WHEN '41343ac9b96e2cf65435179f453a8f2bebb5ea71524ca60e2f0a8613441dcea7' THEN 'Grattis, du löste även Chalmersfallet! Cecilia Wallins vittnesmål var lögn från början till slut, och nu kan både hon och hennes medhjälpare ställas inför rätta. Batteriprototypen är tillbaka på Chalmers. Men lugnet varar inte länge. Den 10 december står Älvsnabben plötsligt still mitt på Göta älv, och över vattnet svävar en drönare som ser exakt ut som Projekt Kråka. Läs brottsplatsrapporterna från den dagen!'
    WHEN 'dd0d3e52ba0dd4e9f5166b690d61589bc79a783a144e23e634c1411912d45ed3' THEN IF(EXISTS (SELECT 1 FROM solution WHERE value = 'Grattis, du löste även Chalmersfallet! Cecilia Wallins vittnesmål var lögn från början till slut, och nu kan både hon och hennes medhjälpare ställas inför rätta. Batteriprototypen är tillbaka på Chalmers. Men lugnet varar inte länge. Den 10 december står Älvsnabben plötsligt still mitt på Göta älv, och över vattnet svävar en drönare som ser exakt ut som Projekt Kråka. Läs brottsplatsrapporterna från den dagen!'), 'Rätt! Andreas Sundberg – mannen som stämde in på allt i Chalmersfallet utom årtalet – är testpilot på Nordvind Drönarteknik AB, Cecilia Wallins bolag. ”Ritningarna kom från chefen. Hon sa att de var våra egna.” Projekt Kråka var borta en hel natt innan polisen hittade den. Det räckte för att kopiera allt. Cecilia sitter nu häktad, men någon fortsätter att sköta hennes affärer. Den 19 januari 2026 anmäler tolv studenter från Yrgo ett företag för bedrägeri. Läs brottsplatsrapporterna från den dagen!', 'Det var tyvärr inte rätt person. Försök igen!')
    WHEN '372d18b53b5357a7e80dc0336808ae5f63fe2c55681de89101653050aef8cbc6' THEN IF(EXISTS (SELECT 1 FROM solution WHERE value = 'Rätt! Andreas Sundberg – mannen som stämde in på allt i Chalmersfallet utom årtalet – är testpilot på Nordvind Drönarteknik AB, Cecilia Wallins bolag. ”Ritningarna kom från chefen. Hon sa att de var våra egna.” Projekt Kråka var borta en hel natt innan polisen hittade den. Det räckte för att kopiera allt. Cecilia sitter nu häktad, men någon fortsätter att sköta hennes affärer. Den 19 januari 2026 anmäler tolv studenter från Yrgo ett företag för bedrägeri. Läs brottsplatsrapporterna från den dagen!'), 'Rätt spår! Åke Blomqvist är bara en målvakt som har lånat ut sitt namn. Vem ligger bakom? Läs hans förhör.', 'Det var tyvärr inte rätt person. Försök igen!')
    WHEN 'c27305cd6dad87d484daacab4430dfe59a23721debbdb9459d0d3c45761165a3' THEN IF(EXISTS (SELECT 1 FROM solution WHERE value = 'Rätt! Andreas Sundberg – mannen som stämde in på allt i Chalmersfallet utom årtalet – är testpilot på Nordvind Drönarteknik AB, Cecilia Wallins bolag. ”Ritningarna kom från chefen. Hon sa att de var våra egna.” Projekt Kråka var borta en hel natt innan polisen hittade den. Det räckte för att kopiera allt. Cecilia sitter nu häktad, men någon fortsätter att sköta hennes affärer. Den 19 januari 2026 anmäler tolv studenter från Yrgo ett företag för bedrägeri. Läs brottsplatsrapporterna från den dagen!'), 'Rätt! Annika Holm drev bluffbolagen åt Nordvind medan Cecilia satt häktad. Studenternas källkod skulle bli nästa version av Kråka 2. Studenterna får tillbaka sina avgifter, och Yrgo granskar numera alla LIA-företag extra noga. Hela nätverket kring Cecilia Wallin är avslöjat. Nu är det verkligen dags för en välförtjänt fika!', 'Det var tyvärr inte rätt person. Försök igen!')
    ELSE 'Det var tyvärr inte rätt person. Försök igen!'
END;










